    const phase4Manifest = JSON.parse(await this.app.vault.read(this.app.vault.getAbstractFileByPath('Engineering Knowledge Slicer/v3-phase4/state/v1/manifests/current-run.json')));
    const phase4Kinds = []; for (const path of phase4Manifest.artifacts.entity_paths) { const text = await this.app.vault.read(this.app.vault.getAbstractFileByPath(path)); const kind = text.match(/^entity_kind: (.+)$/m)?.[1]; if (kind && !phase4Kinds.includes(kind)) phase4Kinds.push(kind); } phase4Kinds.sort();
    const p3Index = JSON.parse(await this.app.vault.read(this.app.vault.getAbstractFileByPath(phase3.manifest.index.path))); const indexedTargets = new Set(Object.values(p3Index.records).map((item) => item.path.replace(/\.md$/, ''))); let linksValid = true;
